def page(file,title,desc,body):
    canonical=ORIGIN+'/'+('' if file=='index.html' else file)
    header=HEADER.replace(f'href="{file}">',f'href="{file}" aria-current="page">') if file!='index.html' else HEADER
    out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#061521"><link rel="canonical" href="{canonical}"><link rel="icon" href="assets/mascot.avif" type="image/avif"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/anniversary-logo.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="styles.css"><script type="application/ld+json">{json.dumps(schema)}</script></head><body><noscript><style>@media(max-width:760px){{.site-header{{height:auto;position:relative}}.header-inner{{flex-wrap:wrap;padding:10px 0}}.menu-toggle{{display:none}}.nav{{display:flex;position:static;width:100%;padding:12px;gap:4px}}}}</style></noscript>{header}<main id="main">{body}</main>{FOOTER}</body></html>'''
    out=out.replace('<link rel="stylesheet" href="styles.css">','<link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="reviews.css">')
    if file=='reviews.html':out=out.replace('</body>','<script src="reviews.js" defer></script></body>')
    (D/file).write_text(out,encoding='utf-8')
